using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ENC.Respuestas;namespace GraphApi.Services.ENC.Respuestas{    public class RespuestasService : IRespuestasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public RespuestasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadRespuestas>> GetRespuestas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM enc.Respuestas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadRespuestas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetRespuestasDynamic(            int? respuestaID,            int? encuestaID,            int? preguntaID,            int? usuarioID,            int? opcionPreguntaID,            string? respuestaTexto,            DateTime? fechaRespuesta,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "RespuestaID, EncuestaID, PreguntaID, UsuarioID, OpcionPreguntaID, RespuestaTexto, FechaRespuesta, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM enc.Respuestas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (respuestaID.HasValue)            {                vSql.Append(" AND RespuestaID = @RespuestaID");                vParameters.Add("RespuestaID",respuestaID);            }            if (!string.IsNullOrWhiteSpace(respuestaTexto))            {                vSql.Append(" AND RespuestaTexto LIKE @RespuestaTexto");                vParameters.Add("RespuestaTexto",$"%{respuestaTexto}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadRespuestas> CreateRespuestas(clCreateRespuestas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO enc.Respuestas                (EncuestaID, PreguntaID, UsuarioID, OpcionPreguntaID, RespuestaTexto, FechaRespuesta, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@EncuestaID, @PreguntaID, @UsuarioID, @OpcionPreguntaID, @RespuestaTexto, @FechaRespuesta, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.EncuestaID,                objInput.PreguntaID,                objInput.UsuarioID,                objInput.OpcionPreguntaID,                objInput.RespuestaTexto,                objInput.FechaRespuesta,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT RespuestaID, EncuestaID, PreguntaID, UsuarioID, OpcionPreguntaID, RespuestaTexto, FechaRespuesta, bEliminado                FROM enc.Respuestas (NOLOCK)                WHERE RespuestaID = @RespuestaID;";            var vReadParams = new { RespuestaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadRespuestas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Respuesta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadRespuestas?> UpdateRespuestas(clUpdateRespuestas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("RespuestaID", objInput.RespuestaID);            if (objInput.EncuestaID != null)            {                vSets.Add("EncuestaID = @EncuestaID");                vParameters.Add("EncuestaID", objInput.EncuestaID);            }            if (objInput.PreguntaID != null)            {                vSets.Add("PreguntaID = @PreguntaID");                vParameters.Add("PreguntaID", objInput.PreguntaID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.OpcionPreguntaID != null)            {                vSets.Add("OpcionPreguntaID = @OpcionPreguntaID");                vParameters.Add("OpcionPreguntaID", objInput.OpcionPreguntaID);            }            if (objInput.RespuestaTexto is not null)            {                vSets.Add("RespuestaTexto = @RespuestaTexto");                vParameters.Add("RespuestaTexto", objInput.RespuestaTexto);            }            if (objInput.FechaRespuesta != null)            {                vSets.Add("FechaRespuesta = @FechaRespuesta");                vParameters.Add("FechaRespuesta", objInput.FechaRespuesta);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE enc.Respuestas                SET {vSetClause}                WHERE RespuestaID = @RespuestaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT RespuestaID, EncuestaID, PreguntaID, UsuarioID, OpcionPreguntaID, RespuestaTexto, FechaRespuesta, bEliminado                FROM enc.Respuestas (NOLOCK)                WHERE RespuestaID = @RespuestaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadRespuestas>(sSelect, new {  objInput.RespuestaID });        }        public async Task<bool> DeleteRespuestas(int nRespuestasID)        {            const string sSql = @"                DELETE FROM enc.Respuestas                WHERE RespuestaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nRespuestasID });            return vAffected > 0;        }    }}